func ValidateEvaluateConditionalAccessResponseBody(body *EvaluateConditionalAccessResponseBody) (err error) {
	if body.Decision == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("decision", "body"))
	}
	if body.Reason == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("reason", "body"))
	}
	if body.ConfidenceScore == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("confidence_score", "body"))
	}
	if body.Decision != nil {
		if !(*body.Decision == "allow" || *body.Decision == "deny" || *body.Decision == "challenge") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.decision", *body.Decision, []any{"allow", "deny", "challenge"}))
		}
	}
	if body.ConfidenceScore != nil {
		if *body.ConfidenceScore < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.confidence_score", *body.ConfidenceScore, 0, true))
		}
	}
	if body.ConfidenceScore != nil {
		if *body.ConfidenceScore > 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.confidence_score", *body.ConfidenceScore, 1, false))
		}
	}
	if body.ValidUntil != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.valid_until", *body.ValidUntil, goa.FormatDateTime))
	}
	return
}

